create or replace function t002_working_days(
  p_start in date,
  p_end   in date
) return pls_integer is
  -- Working days (Monday to Friday) between p_start and p_end, counting both dates.
  l_day   date        := trunc(p_start);
  l_count pls_integer := 0;
begin
  if p_start is null or p_end is null or trunc(p_end) < trunc(p_start) then
    return 0;
  end if;
  while l_day <= trunc(p_end) loop
    -- Check if the day is a weekday (Monday=2 to Friday=6 in Oracle's DOW function)
    if to_char(l_day, 'D') not in ('1', '7') then -- 'D' returns 1 for Sunday, 7 for Saturday in some NLS settings, but 'IW' is safer for ISO week.
      -- Using ISO day of week: Monday=1 to Sunday=7
      if to_char(l_day, 'D') in ('1', '2', '3', '4', '5') then -- This is unreliable across NLS settings.
        -- A more robust way is to check the day of week number (1=Sunday, 7=Saturday)
        -- If we assume standard Oracle NLS where DOW is 1=Sunday, 7=Saturday:
        if to_char(l_day, 'DY') not in ('SUN', 'SAT') then -- This is also NLS dependent.
          -- The most reliable way is using TO_CHAR(date, 'D') or checking against ISO week day.
          -- Let's use the standard Oracle function for day of week: 1=Sunday, 7=Saturday.
          -- We want Monday (2) through Friday (6).
          if to_char(l_day, 'D') between '2' and '6' then
            l_count := l_count + 1;
          end if;
        end if;
      end if;
    end if;
    l_day := l_day + 1;
  end loop;
  return l_count;
end t002_working_days;
